    n, m = map(int, sys.stdin.readline().split())
    tiling = [sys.stdin.readline().strip() for _ in range(n)]

    def find_moves(x, y):
        moves = set()
        if tiling[x][y] == 'U':
            if x + 1 < n and tiling[x + 1][y] == 'D':
                moves.add((x + 1, y))
        elif tiling[x][y] == 'D':
            if x - 1 >= 0 and tiling[x - 1][y] == 'U':
                moves.add((x - 1, y))
        elif tiling[x][y] == 'L':
            if y + 1 < m and tiling[x][y + 1] == 'R':
                moves.add((x, y + 1))
        elif tiling[x][y] == 'R':
            if y - 1 >= 0 and tiling[x][y - 1] == 'L':
                moves.add((x, y - 1))
        return moves

    def bfs(start_x, start_y):
        queue = [(start_x, start_y)]
        visited = set([(start_x, start_y)])
        while queue:
            x, y = queue.pop(0)
            for nx, ny in find_moves(x, y):
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
        return visited

    def get_free_cells():
        free_cells = []
        for i in range(n):
            for j in range(m):
                if (i + j) % 2 == 0:
                    free_cells.append((i, j))
        return free_cells

    def get_photo(x, y):
        visited = bfs(x, y)
        photo = set()
        for i in range(n):
            for j in range(m):
                pair = (i, j) if (i + j) % 2 == 0 else (i, j - 1) if j > 0 else (i + 1, j)
                if pair not in visited:
                    photo.add(pair)
        return frozenset(photo)

    free_cells = get_free_cells()
    distinct_photos = set()

    for x, y in free_cells:
        photo = get_photo(x, y)
        distinct_photos.add(photo)

    print(len(distinct_photos))

